# Smoke tests for «الطائر الذهبي» (Golden Bird): runs pytest on this folder, then prints one summary line in Arabic.

#   powershell -ExecutionPolicy Bypass -File tests\run_tests.ps1

# Offline and fast: no API key, no window, no Claude call; temp files only under %TEMP%; nothing written into app\.

# Exit 0 = everything passed (skips and known-bug xfails are allowed), 1 = a test failed or the tests could not run.

# app\build.ps1 runs this before every build (the gate is generated by forge\make_golden_bird.py; -SkipTests skips it).

param()

$ErrorActionPreference = "Continue"

$sw = [Diagnostics.Stopwatch]::StartNew()

$oldEnc = [Console]::OutputEncoding

try { [Console]::OutputEncoding = [Text.Encoding]::UTF8 } catch {}       # python prints UTF-8 (Arabic test names/reasons)

$junit = Join-Path ([IO.Path]::GetTempPath()) ("gb_tests_{0}.xml" -f $PID)

$code = 1

try {

  if (-not (Get-Command python -ErrorAction SilentlyContinue)) {

    $line = "✗ الاختبارات ماشتغلتش: python مش موجود على الـ PATH"

  } else {

    python -X utf8 -B -c "import pytest" 2>$null

    if ($LASTEXITCODE -ne 0) {

      $line = "✗ الاختبارات ماشتغلتش: pytest مش موجود (python -m pip install pytest)"

    } else {

      python -X utf8 -B -m pytest $PSScriptRoot -q --tb=short -rfEsxX "--junitxml=$junit"

      $rc = $LASTEXITCODE

      $secs = "{0:0.0}" -f $sw.Elapsed.TotalSeconds

      if (Test-Path -LiteralPath $junit) {

        $x = [xml](Get-Content -LiteralPath $junit -Raw -Encoding UTF8)

        $all = $x.SelectNodes("//testcase").Count

        $failed = $x.SelectNodes("//testcase[failure or error]").Count

        $xfail = $x.SelectNodes("//testcase/skipped[@type='pytest.xfail']").Count

        $skipped = $x.SelectNodes("//testcase/skipped").Count - $xfail

        $passed = $all - $failed - $skipped - $xfail

        if ($rc -eq 0) {

          $code = 0

          $line = "✓ اختبارات الطائر الذهبي عدّت: $passed نجح، $skipped اتخطّى، $xfail باج معروف، في $secs ث"

        } else {

          $line = "✗ اختبارات الطائر الذهبي فشلت: $failed فشل، $passed نجح، $skipped اتخطّى، $xfail باج معروف، في $secs ث"

        }

      } else {

        $line = "✗ الاختبارات ماكمّلتش (pytest خرج بكود $rc) في $secs ث"

      }

    }

  }

} finally {

  Remove-Item -LiteralPath $junit -Force -ErrorAction SilentlyContinue

}

Write-Output $line

try { [Console]::OutputEncoding = $oldEnc } catch {}

exit $code

